
let paused=false,selected=null,revision=1,jobs=[{id:'demo-1',title:'Original sample video',state:'downloading',progress:42},{id:'demo-2',title:'Original guide',state:'completed',progress:100,fileId:'file-demo'}];if(window.omnibloomHost)jobs=[];function draw(){const box=document.getElementById('jobs');box.replaceChildren();jobs.slice(0,3).forEach(job=>{const card=document.createElement('section');card.className='card';const row=document.createElement('div');row.className='row spread';const h=document.createElement('h2');h.textContent=job.title;const state=document.createElement('span');state.className='badge neutral';state.textContent=job.state;row.append(h,state);const progress=document.createElement('progress');progress.max=100;progress.value=job.progress??0;progress.setAttribute('aria-label',job.title+' progress');card.append(row,progress);if(job.state==='completed'){const b=document.createElement('button');b.textContent='Open or send';b.onclick=()=>{selected=job;document.getElementById('job-title').textContent=job.title;obUI.openDialog('job-options')};card.append(b)}box.append(card)});if(!jobs.length)box.innerHTML='<p class="empty">No downloads yet.</p>'}
document.getElementById('queue').onclick=async()=>{try{await r2.request('downloads.queue',{paused:!paused},()=>true);paused=!paused;document.getElementById('queue').textContent=paused?'Resume queue':'Pause queue';document.getElementById('queue-status').textContent=paused?'Queue paused · active transfer may continue':'Queue running'}catch(e){r2.toast(e.message)}};async function fileAction(method){try{await r2.request(method,{jobId:selected.id,fileId:selected.fileId},()=>true);document.getElementById('job-options').close();r2.toast(method==='downloads.open'?'Open requested in preview.':'USB destination picker requested in preview.');obUI.focus(document.querySelector('#jobs button'))}catch(e){r2.toast(e.message)}}document.getElementById('open-file').onclick=()=>fileAction('downloads.open');document.getElementById('usb').onclick=()=>fileAction('downloads.sendToUSB');window.addEventListener('omnibloom-event',e=>{if(e.detail?.event==='downloads.changed'){jobs=e.detail.payload.jobs;revision=e.detail.payload.revision;const id=document.activeElement?.id;draw();if(document.activeElement===document.body)obUI.focus(document.getElementById(id)||document.getElementById('queue'))}});draw();
if(window.omnibloomHost){document.getElementById('queue').disabled=true;document.getElementById('queue-status').textContent='Downloads unavailable';r2.request('downloads.read',{},null).then(s=>{if(!Array.isArray(s?.jobs))throw Error('Invalid jobs');jobs=s.jobs;paused=!!s.paused;revision=s.revision;draw();document.getElementById('queue').disabled=false;document.getElementById('queue-status').textContent=paused?'Queue paused':'Queue running';}).catch(()=>{});}
